"use client"

import { useState, useEffect } from "react"
import { Wind, AlertTriangle } from "lucide-react"
import { fetchProductos } from "../services/api"
import { motion } from "framer-motion";

const VientosSection = ({ loading: initialLoading }) => {
  const [producto, setProducto] = useState(null)
  const [loading, setLoading] = useState(initialLoading)

  useEffect(() => {
    loadVientosData()
  }, [])

  const loadVientosData = async () => {
    try {
      setLoading(true)
      const response = await fetchProductos({ tipo: "rutas_caminera" })
      const productos = response.results || response
      setProducto(productos[0] || null)
    } catch (error) {
      console.error("Error loading vientos data:", error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 40 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: 'easeOut' }}
      className="bg-white/90 rounded-2xl shadow-2xl p-8 flex flex-col items-center gap-6 min-h-[220px]"
      style={{ backdropFilter: 'blur(4px)' }}
    >
      <Wind className="h-12 w-12 text-blue-500 mb-2" />
      <div className="text-3xl font-bold text-gray-800 mb-1">Vientos en Rutas</div>
      <div className="text-2xl font-extrabold text-blue-700 mb-1">{producto ? `${producto.valor} km/h` : "Sin datos recientes"}</div>
      <div className="text-gray-600 mb-4">{producto ? "Ráfaga máxima actual" : "No hay datos de ráfagas"}</div>
      <div className="w-full">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Escala de Intensidad del Viento</h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-green-50 p-4 rounded-lg border border-green-200">
            <div className="flex items-center space-x-2 mb-2">
              <Wind className="h-5 w-5 text-green-600" />
              <span className="font-semibold text-green-800">Suave</span>
            </div>
            <p className="text-sm text-green-700">0-20</p>
          </div>
          {/* Puedes agregar más categorías aquí */}
        </div>
      </div>
    </motion.div>
  )
}

export default VientosSection
